for slug,(name,title,intro,details,label,options,hint) in pages.items():
    detail=''.join(f'<article class="client-detail"><h2>{a}</h2><p>{b}</p></article>' for a,b in details)
    opts=''.join(f'<option>{o}</option>' for o in options)
    links=' · '.join(f'<a href="{x}.html">{v[0]}</a>' for x,v in pages.items() if x!=slug)
    content=f'''<main id="client-page" class="section active client-page" lang="ru"><div class="container">
<a class="client-breadcrumb" href="URBANLOCK.html#clients">Главная / Для клиентов / {name}</a>
<p class="section-label" style="margin-top:32px">Urban Lock / {name}</p><h1 class="client-heading">{title}</h1><p class="client-intro">{intro}</p>
<div class="hero-actions" style="margin-top:26px"><a class="btn-primary" href="#client-request">Получить консультацию</a><button class="btn-secondary" onclick="orderProduct('Выезд на объект — {name}')">Выезд на объект</button></div>
<div class="client-layout"><div>{detail}<p class="muted">Стоимость оборудования и работ рассчитаем после уточнения задачи. Заявка ни к чему не обязывает.</p><p class="client-other">{links}</p></div>
<section class="client-form-panel" id="client-request"><h2>Рассчитать стоимость</h2>
<form class="urban-form" data-request="{name}">
<label>{label}<select name="{label}" required><option value="">Выберите вариант</option>{opts}</select></label>
<label>Количество парковочных мест<input name="Количество мест" type="number" min="1" step="1" placeholder="Например, 10" {'value="1"' if slug=='private' else ''}></label>
<label>Необходимое оборудование<select name="Оборудование"><option>Нужна консультация</option> <option>Автоматические блокираторы</option><option>Механические блокираторы</option><option>Барьеры</option><option>Шлагбаумы</option><option>Комплексное оснащение</option></select></label>
<label>Город и расположение объекта<input name="Объект / адрес" maxlength="300" placeholder="Город, район или название объекта"></label>
<label>Особенности и объём работ<textarea name="Особенности" placeholder="{hint}" maxlength="2000"></textarea></label>
<label>Нужен выезд на объект?<select name="Выезд"><option>Обсудить на консультации</option><option>Да, нужен выезд</option><option>Пока только расчёт</option></select></label>
<div class="urban-form-row"><label>Ваше имя<input name="Имя" required autocomplete="name" maxlength="100"></label><label>Телефон<input name="Телефон" required type="tel" autocomplete="tel" placeholder="+7 ___ ___ __ __"></label></div>
<button class="btn-primary" type="submit">Рассчитать стоимость</button><p class="form-note">Подготовим текст заявки для WhatsApp. Отправку сообщения подтверждаете вы.</p><div class="request-result" aria-live="polite"></div>
</form></section></div></div></main>'''
    out=shell.replace('id="home" class="section active"','id="home" class="section"')
    out=out.replace('<!-- ===== HOME ===== -->',content+'\n<!-- ===== HOME ===== -->')
    out=re.sub(r'<title>.*?</title>',f'<title>{name} — Urban Lock</title><meta name="description" content="{intro}">',out,count=1)
    # New client content is Russian; avoid suggesting that the whole page is translated.
    out=re.sub(r'<div class="lang-switcher">.*?</div>','',out,count=1,flags=re.S)
    (root/f'{slug}.html').write_text(out)
finish()
print('Built client pages, section pages, prices and SEO metadata.')
